import React, { useEffect, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { listDashboards, deleteDashboard, publishDashboard, listMetabaseDashboards, getMetabaseDashboard } from '../services/api';

const emptyConfig = {
  collection: { name: '', description: '', parentId: null },
  dashboard: { name: '', description: '', pin: false, tabs: [] },
  cards: [],
  filters: [],
  groups: [],
};

const asArray = (value) => {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.data)) return value.data;
  return [];
};

const copyText = (value) => `${value || 'Untitled Dashboard'} (Copy)`;

const cloneConfig = (config = emptyConfig, name, description) => {
  const cloned = JSON.parse(JSON.stringify({ ...emptyConfig, ...config }));
  cloned.collection = { ...emptyConfig.collection, ...(cloned.collection || {}) };
  cloned.dashboard = {
    ...emptyConfig.dashboard,
    ...(cloned.dashboard || {}),
    name: copyText(cloned.dashboard?.name || name),
    description: cloned.dashboard?.description || description || '',
  };
  cloned.cards = asArray(cloned.cards).map(card => ({
    ...card,
    id: uuidv4(),
    title: copyText(card.title),
    col: (card.col ?? 0) + 1,
    row: (card.row ?? 0) + 1,
  }));
  cloned.filters = asArray(cloned.filters).map(filter => ({ ...filter, id: uuidv4().slice(0, 8) }));
  cloned.groups = asArray(cloned.groups);
  return cloned;
};

const getDashboardLink = (dashboard) => {
  if (dashboard.public_uuid) return `/public/dashboard/${dashboard.public_uuid}`;
  if (dashboard.id) return `/dashboard/${dashboard.id}`;
  return '#';
};

export default function DashboardList({ onOpen, onCreate }) {
  const [dashboards, setDashboards] = useState([]);
  const [metabaseDashboards, setMetabaseDashboards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [publishing, setPublishing] = useState(null);
  const [remoteLoading, setRemoteLoading] = useState(null);
  const [message, setMessage] = useState(null);

  const load = () => {
    setLoading(true);
    setMessage(null);
    Promise.all([
      listDashboards(),
      listMetabaseDashboards()
    ])
      .then(([configs, metabase]) => {
        setDashboards(asArray(configs));
        setMetabaseDashboards(asArray(metabase));
      })
      .catch(e => {
        setMessage({ type: 'error', text: e.response?.data?.error || e.message });
      })
      .finally(() => setLoading(false));
  };

  useEffect(load, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this dashboard config?')) return;
    await deleteDashboard(id);
    load();
  };

  const handlePublish = async (id) => {
    setPublishing(id);
    setMessage(null);
    try {
      const res = await publishDashboard(id);
      setMessage({ type: 'success', text: `Published! Metabase Dashboard ID: ${res.dashboardId}` });
      load();
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setPublishing(null);
    }
  };

  const buildMetabaseDraft = async (dashboard, duplicate = false) => {
    const remote = await getMetabaseDashboard(dashboard.id);
    const rawCards = remote.ordered_cards || remote.cards || [];
    const cards = rawCards.map((item, index) => {
      const card = item.card || item;
      const datasetQuery = card.dataset_query || card.query || {};
      let query = '';

      if (datasetQuery.type === 'native') {
        query = datasetQuery.native?.query || '';
      } else if (datasetQuery.type === 'query') {
        if (typeof datasetQuery.query === 'string') {
          query = datasetQuery.query;
        } else {
          query = JSON.stringify(datasetQuery.query || '');
        }
      } else if (typeof datasetQuery === 'string') {
        query = datasetQuery;
      } else if (Array.isArray(datasetQuery)) {
        query = datasetQuery[0]?.query || '';
      }

      const type = (() => {
        const graphType = card.visualization_settings?.graph_type || card.visualization_settings?.type;
        if (graphType === 'bar') return 'bar';
        if (graphType === 'line') return 'line';
        if (graphType === 'pie') return 'pie';
        if (graphType === 'area') return 'area';
        if (graphType === 'scalar') return 'scalar';
        return 'table';
      })();

      return {
        id: uuidv4(),
        title: duplicate ? copyText(card.name || card.display_name || `Card ${index + 1}`) : (card.name || card.display_name || `Card ${index + 1}`),
        type,
        query,
        visualization_settings: card.visualization_settings || {},
        col: item.position?.x ?? item.x ?? item.col ?? 0,
        row: item.position?.y ?? item.y ?? item.row ?? index * 4,
        sizeX: item.size?.x ?? item.sizeX ?? item.w ?? 6,
        sizeY: item.size?.y ?? item.sizeY ?? item.h ?? 4,
        tabIndex: undefined,
        parameterMappings: card.parameter_mappings || item.parameter_mappings || [],
        templateTags: card.dataset_query?.native?.template_tags || {},
      };
    });

    const name = duplicate ? copyText(remote.name || dashboard.name) : (remote.name || dashboard.name);
    const description = remote.description || dashboard.description || '';

    return {
      id: uuidv4(),
      name,
      description,
      config: {
        collection: { name: '', description: '', parentId: null },
        dashboard: {
          name,
          description,
          pin: false,
          tabs: [],
        },
        cards,
        filters: [],
        groups: [],
      },
      status: 'draft',
    };
  };

  const handleEditMetabase = async (dashboard) => {
    setMessage(null);
    setRemoteLoading(`edit-${dashboard.id}`);
    try {
      onOpen && onOpen(await buildMetabaseDraft(dashboard));
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setRemoteLoading(null);
    }
  };

  const handleDuplicateSaved = (dashboard) => {
    const name = copyText(dashboard.name);
    onOpen && onOpen({
      id: uuidv4(),
      name,
      description: dashboard.description || '',
      config: cloneConfig(dashboard.config, dashboard.name, dashboard.description),
      status: 'draft',
    });
  };

  const handleDuplicateMetabase = async (dashboard) => {
    setMessage(null);
    setRemoteLoading(`duplicate-${dashboard.id}`);
    try {
      onOpen && onOpen(await buildMetabaseDraft(dashboard, true));
    } catch (e) {
      setMessage({ type: 'error', text: e.response?.data?.error || e.message });
    } finally {
      setRemoteLoading(null);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h2 style={styles.pageTitle}>Dashboards</h2>
          <p style={styles.subtitle}>Open, duplicate, publish, or import dashboards into the builder.</p>
        </div>
        <button style={styles.createBtn} onClick={onCreate}>+ New Dashboard</button>
      </div>

      {message && (
        <div style={{ ...styles.alert, background: message.type === 'success' ? '#d3f9d8' : '#ffe3e3', color: message.type === 'success' ? '#2f9e44' : '#c92a2a' }}>
          {message.text}
        </div>
      )}

      <section style={styles.section}>
        <div style={styles.sectionHeader}>
          <div>
            <h3 style={styles.sectionTitle}>Saved Dashboard Configs</h3>
            <p style={styles.sectionHelp}>Drafts and dashboards created from this builder.</p>
          </div>
          <span style={styles.countBadge}>{dashboards.length}</span>
        </div>

        {loading ? <p style={styles.muted}>Loading dashboards...</p> : (
          <div style={styles.savedList}>
            {dashboards.map(d => (
              <div key={d.id} style={styles.savedRow}>
                <div style={styles.savedMain}>
                  <div style={styles.savedTitle}>{d.name}</div>
                  {d.description && <div style={styles.savedDescription}>{d.description}</div>}
                  <div style={styles.metaLine}>
                    <span style={{ ...styles.badge, background: d.status === 'published' ? '#d3f9d8' : '#fff3bf' }}>{d.status || 'draft'}</span>
                    <span>{d.metabase_dashboard_id ? `Metabase ID: ${d.metabase_dashboard_id}` : 'Not published'}</span>
                    {d.updated_at && <span>Updated {new Date(d.updated_at).toLocaleString()}</span>}
                  </div>
                </div>
                <div style={styles.rowActions}>
                  <button style={styles.primaryActionBtn} onClick={() => onOpen(d)}>Edit</button>
                  <button style={styles.actionBtn} onClick={() => handleDuplicateSaved(d)}>Duplicate</button>
                  <button
                    style={{ ...styles.actionBtn, background: '#2f9e44', color: '#fff', borderColor: '#2f9e44' }}
                    onClick={() => handlePublish(d.id)}
                    disabled={publishing === d.id}
                  >
                    {publishing === d.id ? 'Publishing...' : 'Publish'}
                  </button>
                  <button
                    style={{ ...styles.actionBtn, background: '#fff5f5', color: '#c92a2a', borderColor: '#ffc9c9' }}
                    onClick={() => handleDelete(d.id)}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
            {dashboards.length === 0 && (
              <div style={styles.emptyState}>No saved dashboards yet. Create one or import from Metabase below.</div>
            )}
          </div>
        )}
      </section>

      <section style={styles.section}>
        <div style={styles.sectionHeader}>
          <div>
            <h3 style={styles.sectionTitle}>Metabase Dashboards</h3>
            <p style={styles.sectionHelp}>Edit imports the dashboard data into a new builder draft.</p>
          </div>
          <span style={styles.countBadge}>{metabaseDashboards.length}</span>
        </div>
        {loading ? (
          <p style={styles.muted}>Loading Metabase dashboards...</p>
        ) : metabaseDashboards.length > 0 ? (
          <div style={styles.dashboardGrid}>
            {metabaseDashboards.map(d => (
              <div key={d.id} style={styles.dashboardCard}>
                <div style={styles.cardTopline}>
                  <h4 style={styles.cardTitle}>{d.name}</h4>
                  <span style={styles.idPill}>#{d.id}</span>
                </div>
                {d.description && <p style={styles.cardDescription}>{d.description}</p>}
                <div style={styles.cardMeta}>
                  <span>{d.collection?.name || d.collection_name || 'Metabase'}</span>
                  {d.updated_at && <span>Updated {new Date(d.updated_at).toLocaleString()}</span>}
                </div>
                <div style={styles.cardActions}>
                  <button
                    style={styles.primaryActionBtn}
                    onClick={() => handleEditMetabase(d)}
                    disabled={remoteLoading === `edit-${d.id}`}
                  >
                    {remoteLoading === `edit-${d.id}` ? 'Loading...' : 'Edit'}
                  </button>
                  <button
                    style={styles.actionBtn}
                    onClick={() => handleDuplicateMetabase(d)}
                    disabled={remoteLoading === `duplicate-${d.id}`}
                  >
                    {remoteLoading === `duplicate-${d.id}` ? 'Duplicating...' : 'Duplicate'}
                  </button>
                  <a
                    href={getDashboardLink(d)}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={styles.viewBtn}
                  >
                    View
                  </a>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div style={styles.emptyState}>No Metabase dashboards found.</div>
        )}
      </section>
    </div>
  );
}

const styles = {
  page: { padding: 32, maxWidth: 1120, margin: '0 auto', fontFamily: 'system-ui, sans-serif', color: '#212529' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16, marginBottom: 24 },
  pageTitle: { margin: 0, fontSize: 28, letterSpacing: 0 },
  subtitle: { margin: '6px 0 0', color: '#6c757d', fontSize: 14 },
  createBtn: { padding: '10px 20px', background: '#4c6ef5', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: 14 },
  alert: { padding: '10px 16px', borderRadius: 8, marginBottom: 16, fontSize: 13 },
  section: { marginBottom: 32 },
  sectionHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16, marginBottom: 14 },
  sectionTitle: { margin: 0, fontSize: 18 },
  sectionHelp: { margin: '4px 0 0', color: '#868e96', fontSize: 13 },
  countBadge: { minWidth: 28, textAlign: 'center', padding: '3px 8px', borderRadius: 999, background: '#f1f3f5', color: '#495057', fontSize: 12, fontWeight: 700 },
