  savedDescription: { marginTop: 3, color: '#6c757d', fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' },
  metaLine: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8, marginTop: 8, color: '#868e96', fontSize: 12 },
  rowActions: { display: 'flex', justifyContent: 'flex-end', gap: 6, flexWrap: 'wrap', flexShrink: 0 },
  badge: { padding: '2px 8px', borderRadius: 12, fontSize: 11, fontWeight: 600 },
  primaryActionBtn: { padding: '6px 12px', border: '1px solid #4c6ef5', borderRadius: 6, cursor: 'pointer', fontSize: 12, background: '#4c6ef5', color: '#fff', fontWeight: 700 },
  actionBtn: { padding: '6px 12px', border: '1px solid #dee2e6', borderRadius: 6, cursor: 'pointer', fontSize: 12, background: '#fff', color: '#343a40', fontWeight: 600 },
